const event = $input.first().json.event || $input.first().json;
const payload = event.payload || {};

const systemPrompt = `Eres el especialista en diseño de objetivos y hojas de ruta de RAX.\nTu misión es proponer objetivos SMART vinculados al diagnóstico y estructurar un plan de acción.\nREGLAS:\n1. Cada objetivo debe contar con línea base (baseline), resultado esperado (targetResult), indicador verificable y prioridad.\n2. Distingue entre la meta final y las actividades requeridas.\n3. No impongas métricas artificiales; si un objetivo no puede medirse numéricamente, formula un indicador cualitativo verificable.\n4. Salida en JSON estricto con: proposedGoals (array de objetos con title, description, whyItMatters, kind, baseline, targetResult, metricIndicator, priority), milestoneSuggestions (array), uncertainties (array).`;

const userPrompt = JSON.stringify({
  projectId: event.projectId,
  relationshipId: event.relationshipId,
  confirmedDiagnosis: payload.confirmedDiagnosis || [],
  prioritizedProblems: payload.prioritizedProblems || [],
  founderContext: payload.founderContext || {}
});

return [{
  json: {
    correlationId: event.correlationId || 'corr_' + Date.now(),
    callbackUrl: event.callback?.url || ($env.RAX_API_URL || 'http://localhost:3000') + '/api/n8n/callback',
    model: $env.OPENROUTER_MODEL || 'meta-llama/llama-3.3-70b-instruct:free',
    apiKey: $env.OPENROUTER_API_KEY || '',
    systemPrompt,
    userPrompt
  }
}];

const response = $input.first().json;
const prep = $('Build Goals Prompt').first().json;

let parsed = {};
try {
  const content = response.choices?.[0]?.message?.content || '{}';
  parsed = JSON.parse(content);
} catch (e) {
  parsed = { proposedGoals: [], uncertainties: ['Salida JSON no válida'] };
}

const proposals = (parsed.proposedGoals || []).map(g => ({
  type: 'goal',
  title: g.title,
  description: `${g.description || ''} | Línea base: ${g.baseline || 'N/A'} | Meta: ${g.targetResult || 'N/A'}`,
  successCriteria: g.metricIndicator || undefined,
  needsHumanApproval: true,
  uncertainties: []
}));

const callbackPayload = {
  operationId: 'op_gol_' + Date.now(),
  correlationId: prep.correlationId,
  workflowId: 'RAX-07',
  workflowVersion: '1.0.0',
  status: 'completed',
  usage: {
    model: response.model || prep.model,
    promptTokens: response.usage?.prompt_tokens || 0,
    completionTokens: response.usage?.completion_tokens || 0
  },
  data: {
    summary: `Se estructuraron ${proposals.length} propuestas de objetivos SMART.`,
    proposals,
    uncertainties: parsed.uncertainties || [],
    nextStepRecommendation: (parsed.milestoneSuggestions || []).join(' -> ')
  }
};

return [{
  json: {
    callbackUrl: prep.callbackUrl,
    payload: callbackPayload
  }
}];
